package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.RepositoryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** A second connection on the thread of a NONE connection that rolled back must still read normally. */
class LmdbNoneRollbackSameThreadReadTest {

	private static final ValueFactory F = SimpleValueFactory.getInstance();
	private static final IRI S = F.createIRI("http://example.org/same-thread/s");
	private static final IRI P = F.createIRI("http://example.org/same-thread/p");

	@TempDir
	File dataDir;

	private SailRepository repo;

	@AfterEach
	void tearDown() {
		if (repo != null) {
			repo.shutDown();
		}
	}

	@Test
	void aReadOnAnotherConnectionAfterANoneRollbackSucceeds() {
		repo = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		repo.init();
		try (RepositoryConnection connection = repo.getConnection()) {
			connection.add(S, P, F.createIRI("http://example.org/same-thread/kept"));
		}
		try (RepositoryConnection writer = repo.getConnection()) {
			writer.begin(IsolationLevels.NONE);
			writer.add(S, P, F.createIRI("http://example.org/same-thread/rolled-back"));
			writer.rollback();
			try (RepositoryConnection reader = repo.getConnection()) {
				List<Statement> statements = new ArrayList<>();
				try (RepositoryResult<Statement> result = reader.getStatements(S, P, null, false)) {
					result.forEach(statements::add);
				}
				assertThat(statements)
						.contains(F.createStatement(S, P, F.createIRI("http://example.org/same-thread/kept")));
			}
		}
	}
}
